from solution import change_base
import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference_change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    n = x
    while n > 0:
        digits.append(str(n % base))
        n //= base
    return "".join(reversed(digits))


def test_example_8_base_3():
    assert change_base(8, 3) == '22'


def test_example_8_base_2():
    assert change_base(8, 2) == '1000'


def test_example_7_base_2():
    assert change_base(7, 2) == '111'


def test_zero_returns_zero_string():
    for base in range(2, 10):
        assert change_base(0, base) == "0"


def test_one_returns_one():
    for base in range(2, 10):
        assert change_base(1, base) == "1"


def test_base_itself_is_one_zero():
    for base in range(2, 10):
        assert change_base(base, base) == "10"


def test_max_single_digit():
    for base in range(2, 10):
        assert change_base(base - 1, base) == str(base - 1)


@given(x=st.integers(min_value=0, max_value=100000),
       base=st.integers(min_value=2, max_value=9))
def test_roundtrip_value_preserved(x, base):
    s = change_base(x, base)
    assert isinstance(s, str)
    assert s != ""
    assert int(s, base) == x


@given(x=st.integers(min_value=0, max_value=100000),
       base=st.integers(min_value=2, max_value=9))
def test_equivalence_to_reference_model(x, base):
    assert change_base(x, base) == reference_change_base(x, base)


@given(x=st.integers(min_value=0, max_value=100000),
       base=st.integers(min_value=2, max_value=9))
def test_digits_are_valid_decimal_digits_less_than_base(x, base):
    s = change_base(x, base)
    assert len(s) > 0
    assert all(c.isdigit() for c in s)
    assert all(int(c) < base for c in s)


@given(x=st.integers(min_value=0, max_value=100000),
       base=st.integers(min_value=2, max_value=9))
def test_no_leading_zeros(x, base):
    s = change_base(x, base)
    if len(s) > 1:
        assert s[0] != '0'


@given(k=st.integers(min_value=0, max_value=10),
       base=st.integers(min_value=2, max_value=9))
def test_power_of_base_is_one_followed_by_zeros(k, base):
    x = base ** k
    assert change_base(x, base) == "1" + "0" * k


@given(x=st.integers(min_value=0, max_value=5000),
       base=st.integers(min_value=2, max_value=9),
       k=st.integers(min_value=0, max_value=6))
def test_appending_zero_digit_multiplies_by_base(x, base, k):
    # s + '0'*k in base `base` must equal x * base**k
    s = change_base(x, base)
    shifted = s + "0" * k
    assert int(shifted, base) == x * (base ** k)


@given(x=st.integers(min_value=1, max_value=100000),
       base=st.integers(min_value=2, max_value=9))
def test_length_grows_without_bound_and_last_digit_is_remainder(x, base):
    s = change_base(x, base)
    assert int(s[-1]) == x % base
    # removing last digit corresponds to floor division
    prefix = s[:-1]
    if prefix == "":
        assert x // base == 0
    else:
        assert int(prefix, base) == x // base
